#include <vector>
#include <omp.h>

bool reduceLogicalXOR(std::vector<bool> const& x) {
    // XOR reduction: identity is false
    bool result = false;

    #pragma omp parallel for reduction(^ : result)
    for (std::size_t i = 0; i < x.size(); ++i) {
        // vector<bool> returns a proxy; cast to bool explicitly
        result = result ^ static_cast<bool>(x[i]);
    }

    return result;
}
